cd /app && python - <<'E'
p='statements/meridale.py'
s=open(p).read()
i=s.index("def _amount")
new='''_LINKS = {
    "US/Pacific": "America/Los_Angeles", "US/Eastern": "America/New_York", "US/Central": "America/Chicago",
    "Asia/Calcutta": "Asia/Kolkata", "Asia/Saigon": "Asia/Ho_Chi_Minh", "Europe/Kiev": "Europe/Kyiv",
    "America/Buenos_Aires": "America/Argentina/Buenos_Aires", "Brazil/East": "America/Sao_Paulo",
    "UTC": "Etc/UTC", "GMT": "Etc/UTC",
}
_LOCALES = {"en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP"}
_ZERO = {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}
_THREE = {"BHD", "JOD", "KWD", "OMR", "TND"}
# locale: (decimal, group, code_before)
_FMT = {
    "en-US": (".", ",", True), "en-GB": (".", ",", True), "ja-JP": (".", ",", True), "en-IN": (".", ",", True),
    "pt-BR": (",", ".", True), "de-DE": (",", ".", False), "es": (",", ".", False),
    "de-CH": (".", "\\u2019", False), "fr-FR": (",", "\\u202f", False),
}


def _zone(tz: str) -> str:
    tz = tz.strip()
    if tz in _LINKS:
        return _LINKS[tz]
    m = re.fullmatch(r"(?:UTC|GMT)?\\s*([+-\\u2212])(\\d{1,2})(?::?(\\d{2}))?", tz)
    if m:
        hours = int(m.group(2))
        if int(m.group(3) or 0) == 0:
            if hours == 0:
                return "Etc/UTC"
            east = m.group(1) == "+"
            return f"Etc/GMT{'-' if east else '+'}{hours}"
    return tz


def _locale(loc: str) -> str:
    tag = re.split(r"[.@]", loc)[0].replace("_", "-")
    if tag in _LOCALES:
        return tag
    lang = tag.split("-")[0]
    return lang if lang in _LOCALES else "en-US"


def _digits(currency: str) -> int:
    return 0 if currency in _ZERO else 3 if currency in _THREE else 2


def _amount(value: str, digits: int) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)


def _group(ints: str, locale: str) -> str:
    if locale == "es" and len(ints) <= 4:
        return ints
    if locale == "en-IN":
        if len(ints) <= 3:
            return ints
        head, tail = ints[:-3], ints[-3:]
        parts = []
        while head:
            parts.insert(0, head[-2:])
            head = head[:-2]
        return ",".join(parts + [tail])
    parts = []
    while ints:
        parts.insert(0, ints[-3:])
        ints = ints[:-3]
    return "\\x00".join(parts)


def _text(value: Decimal, currency: str, locale: str, digits: int) -> str:
    dec, grp, before = _FMT[locale]
    neg = value < 0
    body = f"{abs(value):.{digits}f}"
    ints, _, frac = body.partition(".")
    ints = _group(ints, locale)
    ints = ints.replace("\\x00", grp)
    num = ints + (dec + frac if digits else "")
    if neg:
        num = "-" + num
    return f"{currency}\\u00a0{num}" if before else f"{num}\\u00a0{currency}"


def monthly_statement(transport: Transport, merchant: Merchant, year: int, month: int) -> Statement:
    """The statement of `merchant` for one calendar month, with its days in the merchant's time zone.

    One line per day that has settlements, in day order, with the figures and the text the
    Meridale dashboard shows. Raises ApiError when the API answers with an error.
    """
    first = date(year, month, 1)
    end = date(year + month // 12, month % 12 + 1, 1)
    locale = _locale(merchant.locale)
    params = {
        "merchant_id": merchant.id,
        "tz": _zone(merchant.tz),
        "from": first.isoformat(),
        "to": end.isoformat(),
        "locale": locale,
    }
    report = _call(transport, "GET", f"{BASE}/settlements", params)
    currency = report["currency"]
    nd = _digits(currency)
    lines = []
    for d in report["days"]:
        gross, fees, refunds = (_amount(d[k], nd) for k in ("gross", "fees", "refunds"))
        net = gross - fees - refunds
        lines.append(Line(date.fromisoformat(d["day"]), gross, fees, refunds, net, _text(net, currency, locale, nd)))
    total = sum((line.net for line in lines), Decimal(0)).quantize(Decimal(1).scaleb(-nd))
    return Statement(merchant.id, currency, tuple(lines), total, _text(total, currency, locale, nd))
'''
s=s[:i]+new
s=s.replace("import json\n","import json\nimport re\n").replace("from decimal import Decimal","from decimal import ROUND_HALF_EVEN, Decimal")
open(p,'w').write(s)
E
